<div class="lms-student-delete-modal lms-instructor-delete-modal" data-instructor-delete-modal hidden aria-hidden="true"><div class="lms-student-delete-modal-panel" role="dialog" aria-modal="true" aria-labelledby="instructor-delete-title" aria-describedby="instructor-delete-description"><div class="lms-student-delete-modal-icon" aria-hidden="true">!</div><h2 id="instructor-delete-title">{{ __('lms::ui.auto_c78650e11f') }}</h2><p id="instructor-delete-description"><strong data-instructor-delete-name></strong> {{ __('lms::ui.auto_7a83751f72') }}</p><form method="POST" data-instructor-delete-form>@csrf @method('DELETE')<div class="lms-student-delete-modal-actions"><button type="button" class="lms-btn lms-btn-ghost" data-instructor-delete-cancel>{{ __('lms::ui.auto_ea4788705e') }}</button><button type="submit" class="lms-btn lms-btn-danger">{{ __('lms::ui.auto_a56ed673f2') }}</button></div></form></div></div>
<script>
(() => {
    const modal = document.querySelector('[data-instructor-delete-modal]');
    const form = modal?.querySelector('[data-instructor-delete-form]');
    const name = modal?.querySelector('[data-instructor-delete-name]');
    const cancel = modal?.querySelector('[data-instructor-delete-cancel]');
    let trigger;
    const close = () => { if (!modal) return; modal.hidden = true; modal.setAttribute('aria-hidden', 'true'); document.body.classList.remove('lms-modal-open'); trigger?.focus(); };
    document.querySelectorAll('[data-instructor-delete]').forEach(button => button.addEventListener('click', () => {
        trigger = button;
        form.action = button.dataset.deleteUrl;
        name.textContent = button.dataset.instructorName;
        modal.hidden = false;
        modal.setAttribute('aria-hidden', 'false');
        document.body.classList.add('lms-modal-open');
        cancel.focus();
    }));
    cancel?.addEventListener('click', close);
    modal?.addEventListener('click', event => { if (event.target === modal) close(); });
    document.addEventListener('keydown', event => { if (event.key === 'Escape' && modal && !modal.hidden) close(); });
})();
</script>
